    var s = 0, a = 0;

    if (this.w > 1) {
        this.normalize();
    }

    a = 2 * Math.acos(this.w);
    s = Math.sqrt(1 - this.w * this.w);

    if (s == 0) {  //< x3dom.fields.Eps )
        x = this.x;
        y = this.y;
        z = this.z;
    } else {
        x = this.x / s;
        y = this.y / s;
        z = this.z / s;
    }

    return [new x3dom.fields.SFVec3f(x, y, z), a];
