		for (key in object) {
			if (typeof object[key] === 'object') {
				if (isNaN(parseInt(key))) {
					this.ConvertObject(key, object, element, parentkey.substr(1));
				} else {
					this.ConvertToX3DOM(object[key], key, element, parentkey.substr(1));
				}
			}
		}
