                if (this._cf.skinCoord.node)
                    this._cf.skinCoord.node._vf.point.setValues(this._restCoords);
                
                if (this._cf.skinNormal.node)
                    this._cf.skinNormal.node._vf.vector.setValues(this._restNormals);

                
